employee-bonus.code:
# Write your MySQL query statement below
select name, bonus from Employee E left join Bonus B on E.empId=B.empId
where B.bonus < 1000 or B.empId is null;

managers-with-at-least-5-direct-reports.code:
# Write your MySQL query statement below
-- select C.name from (
-- select name, count(managerId)as contacts from Employee group by name, managerId
-- ) as C where C.contacts >= 5;

select name from Employee as E left join (
    select managerId, count(managerId) as contacts from Employee group by managerId
) as C on E.id = C.managerId where C.contacts >= 5;
